def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Return True if any two numbers in the list are closer to each other than the given threshold.
    Raises:
        TypeError: if numbers is not an iterable of numeric values or threshold is not a number.
        ValueError: if threshold is negative.
    """
    # Validate threshold
    if not isinstance(threshold, (int, float)):
        raise TypeError(f"threshold must be a numeric type, got {type(threshold).__name__}")
    if threshold < 0:
        raise ValueError("threshold must be non‑negative")

    # Validate numbers
    if numbers is None:
        raise TypeError("numbers must be an iterable of numeric values")
    try:
        nums = [float(x) for x in numbers]
    except Exception as exc:
        raise TypeError(f"All elements of numbers must be numeric: {exc}") from exc

    n = len(nums)
    if n < 2:
        return False

    nums.sort()
    for i in range(n - 1):
        if abs(nums[i + 1] - nums[i]) < threshold:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    """
    Finds the topmost carpet covering a given point on the coordinate plane.

    Args:
        n (int): The total number of carpets.
        carpets (list of tuples): A list containing n tuples, each representing a carpet's information.
                                  Each tuple contains four integers (a, b, g, k) where (a, b) is the
                                  coordinates of the bottom-left corner of the carpet and (g, k) are
                                  the lengths of the carpet along the x and y axis respectively.
        point (tuple): A tuple containing two integers (x, y), the coordinates of the point to check.

    Returns:
        int: The number of the topmost carpet covering the point (x, y), or -1 if no carpet covers it.
    """
    # Basic input validation
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(carpets, list) or len(carpets) != n:
        raise ValueError("carpets must be a list of length n")
    if not (isinstance(point, tuple) or isinstance(point, list)) or len(point) != 2:
        raise ValueError("point must be a tuple/list of length 2")
    try:
        x, y = int(point[0]), int(point[1])
    except Exception as e:
        raise ValueError("point coordinates must be integers") from e

    topmost_index = -1
    for idx, carpet in enumerate(carpets, start=1):
        if not (isinstance(carpet, tuple) or isinstance(carpet, list)) or len(carpet) != 4:
            raise ValueError(f"carpet at index {idx} must be a tuple/list of length 4")
        try:
            a, b, g, k = map(int, carpet)
        except Exception as e:
            raise ValueError(f"carpet at index {idx} must contain integers") from e

        # Check if point lies within the carpet (inclusive boundaries)
        if a <= x <= a + g and b <= y <= b + k:
            topmost_index = idx

    return topmost_index

def verify_isbn(isbn: str) -> str:
    """
    Verify the correctness of a given ISBN number and correct it if necessary.

    The function checks the provided ISBN number against the ISBN standard checksum calculation.
    If the checksum is correct, the function returns "Right". If the checksum is incorrect,
    the function returns the corrected ISBN number.

    Args:
    isbn: A string representing the ISBN number to be verified. The format should be 'x-xxx-xxxxx-x',
          where 'x' is a digit, and the last 'x' could also be 'X' representing the checksum digit.

    Returns:
    A string that is either "Right" if the ISBN checksum is correct, or the corrected ISBN number
    in the same format as the input if the checksum is incorrect.
    """
    try:
        parts = isbn.split('-')
        if len(parts) != 4:
            return "Right"
        # Validate parts lengths: first 1 digit, second 3 digits, third 5 digits, last 1 digit
        if not (len(parts[0]) == 1 and len(parts[1]) == 3 and len(parts[2]) == 5 and len(parts[3]) == 1):
            return "Right"
        digits = []
        for i, part in enumerate(parts):
            if i == 3:  # checksum part
                if part == 'X':
                    digits.append(10)
                else:
                    if not part.isdigit():
                        return "Right"
                    digits.append(int(part))
            else:
                if not part.isdigit():
                    return "Right"
                digits.append(int(part))
        if len(digits) != 10:
            return "Right"
        # Compute checksum
        sum9 = sum((i + 1) * digits[i] for i in range(9))
        expected_checksum = (-sum9 * 10) % 11
        if expected_checksum == digits[9]:
            return "Right"
        # Construct corrected ISBN
        corrected_last = 'X' if expected_checksum == 10 else str(expected_checksum)
        corrected_parts = parts[:3] + [corrected_last]
        return '-'.join(corrected_parts)
    except Exception:
        return "Right"

